package apigen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"strings"

	"github.com/noahkiss/flightdeck/api/modules"
)

// Paths of the module tier's generated files (docs/specs/modules.md 6, 9).
const (
	ModulesDir         = "api/modules"
	ManifestSchemaPath = "api/modules/manifest.schema.json"
	BlocksGoPath       = "api/modules/blocks_gen.go"
	BlocksSwiftPath    = "swift/HabAPI/Sources/HabAPI/Blocks.swift"
)

// BlockSchemaPath is the JSON Schema of block vocabulary version v.
func BlockSchemaPath(v int) string { return fmt.Sprintf("%s/blocks-v%d.schema.json", ModulesDir, v) }

// moduleFiles returns the module tier's generated files: one block schema per vocabulary
// version, the manifest schema, and the Go and Swift block types.
func moduleFiles() (map[string][]byte, error) {
	out := map[string][]byte{}
	for v := 1; v <= modules.Version; v++ {
		out[BlockSchemaPath(v)] = BlockSchema(v)
	}
	out[ManifestSchemaPath] = ManifestSchema()
	goSrc, err := BlocksGo()
	if err != nil {
		return nil, err
	}
	out[BlocksGoPath] = goSrc
	out[BlocksSwiftPath] = BlocksSwift()
	return out, nil
}

// obj is a JSON object that keeps its key order, so the schema files read top down.
type obj []kv

type kv struct {
	k string
	v any
}

func (o obj) MarshalJSON() ([]byte, error) {
	var b bytes.Buffer
	b.WriteByte('{')
	for i, e := range o {
		if i > 0 {
			b.WriteByte(',')
		}
		k, _ := json.Marshal(e.k)
		b.Write(k)
		b.WriteByte(':')
		v, err := json.Marshal(e.v)
		if err != nil {
			return nil, err
		}
		b.Write(v)
	}
	b.WriteByte('}')
	return b.Bytes(), nil
}

func render(o obj) []byte {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(o); err != nil {
		panic(err)
	}
	return buf.Bytes()
}

const draft = "https://json-schema.org/draft/2020-12/schema"

func ref(name string) obj { return obj{{"$ref", "#/$defs/" + name}} }

// BlockSchema renders vocabulary version v as a JSON Schema (draft 2020-12). The schema is
// strict: an unknown type, field or word is refused, so `gff-hab modules check` catches typos.
// Clients decode leniently (modules.md 6.4).
func BlockSchema(v int) []byte {
	defs := obj{}
	blocks := modules.BlocksAt(v)
	var types []string
	var branches []any
	for _, b := range blocks {
		types = append(types, b.Type)
		branches = append(branches, obj{
			{"if", obj{{"required", []string{"type"}}, {"properties", obj{{"type", obj{{"const", b.Type}}}}}}},
			{"then", ref(b.Type)},
		})
	}
	defs = append(defs, kv{"block", obj{
		{"description", "Any block. Its type picks the definition that applies."},
		{"type", "object"},
		{"required", []string{"type"}},
		{"properties", obj{{"type", obj{{"enum", types}}}}},
		{"allOf", branches},
	}})
	for _, b := range blocks {
		defs = append(defs, kv{b.Type, blockDef(b)})
	}
	defs = append(defs,
		kv{"tint", obj{
			{"description", "A colour by meaning, or a raw #RRGGBB colour."},
			{"anyOf", []any{obj{{"enum", modules.Tints}}, obj{{"type", "string"}, {"pattern", modules.TintPattern}}}},
		}},
		kv{"symbol", obj{
			{"description", "An SF Symbol name. The terminal shows nothing for a name it does not know."},
			{"type", "string"}, {"maxLength", modules.SymbolMax}, {"pattern", modules.SymbolPattern},
		}},
		kv{"steps", obj{
			{"type", "object"},
			{"required", []string{"total", "current"}},
			{"additionalProperties", false},
			{"properties", obj{
				{"total", obj{{"type", "integer"}, {"minimum", 1}, {"maximum", 1000000}}},
				{"current", obj{{"type", "integer"}, {"minimum", 0}, {"maximum", 1000000}}},
			}},
		}},
		kv{"action", actionDef()},
	)
	return render(obj{
		{"$schema", draft},
		{"$id", fmt.Sprintf("urn:flightdeck:blocks:%d", v)},
		{"title", fmt.Sprintf("Flightdeck block vocabulary %d", v)},
		{"description", fmt.Sprintf("A module's block tree, vocabulary version %d. Generated by internal/apigen from api/modules/vocab.go; do not edit. Rules JSON Schema cannot state (at most %d blocks, depth %d, %d bytes, unique ids, steps.current at most steps.total) are checked by modules.ValidateTree. See docs/specs/modules.md 6 and 9.", v, modules.MaxBlocks, modules.MaxDepth, modules.MaxTreeBytes)},
		{"x-vocabulary", v},
		{"$ref", "#/$defs/block"},
		{"$defs", defs},
	})
}

func blockDef(b modules.BlockDef) obj {
	props := obj{{"type", obj{{"const", b.Type}}}}
	required := []string{"type"}
	for _, f := range modules.Common {
		props = append(props, kv{f.Name, fieldSchema(f)})
	}
	for _, f := range b.Fields {
		props = append(props, kv{f.Name, fieldSchema(f)})
		if f.Required {
			required = append(required, f.Name)
		}
	}
	d := obj{
		{"description", b.Doc},
		{"type", "object"},
		{"required", required},
		{"additionalProperties", false},
		{"properties", props},
	}
	if len(b.ExactlyOne) > 0 {
		var alts []any
		for _, name := range b.ExactlyOne {
			alts = append(alts, obj{{"required", []string{name}}})
		}
		d = append(d, kv{"oneOf", alts})
	}
	return d
}

func fieldSchema(f modules.Field) obj {
	var s obj
	switch f.Kind {
	case modules.KindString:
		s = obj{{"type", "string"}, {"maxLength", f.Max}}
		if f.Name == "id" {
			s = append(s, kv{"minLength", 1}, kv{"pattern", modules.IDPattern})
		}
	case modules.KindBool:
		s = obj{{"type", "boolean"}}
	case modules.KindInt:
		s = obj{{"type", "integer"}, {"minimum", f.Min}, {"maximum", f.Max}}
	case modules.KindFraction:
		s = obj{{"type", "number"}, {"minimum", 0}, {"maximum", 1}}
	case modules.KindWords:
		s = obj{{"enum", f.Words}}
	case modules.KindTint:
		s = ref("tint")
	case modules.KindSymbol:
		s = ref("symbol")
	case modules.KindTime:
		s = obj{{"type", "string"}, {"format", "date-time"}}
	case modules.KindAction:
		s = ref("action")
	case modules.KindSteps:
		s = ref("steps")
	case modules.KindChildren:
		item := ref("block")
		if f.Only != "" {
			item = ref(f.Only)
		}
		s = obj{{"type", "array"}, {"items", item}}
		if f.Min > 0 {
			s = append(s, kv{"minItems", f.Min})
		}
		s = append(s, kv{"maxItems", f.Max})
	case modules.KindLines:
		s = obj{{"type", "array"}, {"items", obj{{"type", "string"}, {"maxLength", f.LineMax}}}, {"maxItems", f.Max}}
	default:
		panic(fmt.Sprintf("modules: field %s has an unknown kind", f.Name))
	}
	if f.Doc != "" {
		s = append(obj{{"description", f.Doc}}, s...)
	}
	return s
}

func actionDef() obj {
	var names []string
	var branches []any
	for _, ca := range modules.ClientActions {
		names = append(names, ca.Name)
		args := obj{}
		for _, a := range ca.Args {
			as := obj{{"type", "string"}, {"minLength", 1}}
			if a == "url" {
				as = append(as, kv{"pattern", modules.URLPattern})
			}
			args = append(args, kv{a, as})
		}
		branches = append(branches, obj{
			{"if", obj{{"properties", obj{{"name", obj{{"const", ca.Name}}}}}}},
			{"then", obj{
				{"required", []string{"args"}},
				{"properties", obj{{"args", obj{{"required", ca.Args}, {"properties", args}}}}},
			}},
		})
	}
	branches = append(branches, obj{
		{"if", obj{{"properties", obj{{"name", obj{{"pattern", "^" + strings.ReplaceAll(modules.ClientPrefix, ".", `\.`)}}}}}}},
		{"then", obj{{"properties", obj{{"name", obj{{"enum", names}}}}}}},
	})
	return obj{
		{"description", "Sent when the block is used. A name the module defines goes to its act function; a client.* name is handled by the client."},
		{"type", "object"},
		{"required", []string{"name"}},
		{"additionalProperties", false},
		{"properties", obj{
			{"name", obj{{"type", "string"}, {"maxLength", modules.ActionMax}, {"pattern", modules.ActionPattern}}},
			{"args", obj{{"type", "object"}}},
		}},
		{"allOf", branches},
	}
}

// ManifestSchema renders the schema of a module's manifest.toml. Stock tools such as
// check-jsonschema read TOML instances directly.
func ManifestSchema() []byte {
	strEnum := func(words []string) obj { return obj{{"enum", words}} }
	setting := obj{
		{"type", "object"},
		{"required", []string{"key", "title", "kind"}},
		{"additionalProperties", false},
		{"properties", obj{
			{"key", obj{{"type", "string"}, {"maxLength", modules.SettingKeyMax}, {"pattern", modules.SettingKeyPattern}}},
			{"title", obj{{"type", "string"}, {"minLength", 1}, {"maxLength", modules.NameMax}}},
			{"kind", strEnum(modules.SettingKinds)},
			{"default", obj{{"description", "Its type follows kind: a string for text and choice, a number, or a boolean for toggle."}}},
			{"choices", obj{{"type", "array"}, {"minItems", 1}, {"items", obj{{"type", "string"}, {"minLength", 1}}}}},
		}},
		{"allOf", []any{
			kindRule("text", obj{{"type", "string"}}),
			kindRule("number", obj{{"type", "number"}}),
			kindRule("toggle", obj{{"type", "boolean"}}),
			obj{
				{"if", obj{{"properties", obj{{"kind", obj{{"const", "choice"}}}}}}},
				{"then", obj{{"required", []string{"choices"}}, {"properties", obj{{"default", obj{{"type", "string"}}}}}}},
				{"else", obj{{"not", obj{{"required", []string{"choices"}}}}}},
			},
		}},
	}
	return render(obj{
		{"$schema", draft},
		{"$id", "urn:flightdeck:module-manifest"},
		{"title", "Flightdeck module manifest"},
		{"description", "A module's manifest.toml. Generated by internal/apigen from api/modules/manifest.go; do not edit. Rules JSON Schema cannot state (unique setting keys, a choice default among its choices) are checked by modules.ParseManifest. See docs/specs/modules.md 5 and 9."},
		{"type", "object"},
		{"required", []string{"id", "name", "version", "blocks", "bridge", "places"}},
		{"additionalProperties", false},
		{"properties", obj{
			{"id", obj{{"description", "Unique on a hab."}, {"type", "string"}, {"maxLength", modules.ModuleIDMax}, {"pattern", modules.ModuleIDPattern}}},
			{"name", obj{{"type", "string"}, {"minLength", 1}, {"maxLength", modules.NameMax}}},
			{"summary", obj{{"type", "string"}, {"maxLength", modules.SummaryMax}}},
			{"version", obj{{"description", "Semver. Shown; not used for gating."}, {"type", "string"}, {"pattern", modules.SemverPattern}}},
			{"blocks", obj{{"description", "The lowest block vocabulary version the module needs."}, {"type", "integer"}, {"minimum", 1}}},
			{"bridge", obj{{"description", "The lowest bridge version the module needs."}, {"type", "integer"}, {"minimum", 1}}},
			{"powers", obj{{"description", "What the module may do beyond reading hab data and keeping state."}, {"type", "array"}, {"uniqueItems", true}, {"items", strEnum(modules.Powers)}}},
			{"places", obj{{"type", "array"}, {"minItems", 1}, {"uniqueItems", true}, {"items", strEnum(modules.Places)}}},
			{"refresh", obj{{"description", fmt.Sprintf("Seconds between scheduled refreshes; below %d is raised to %d.", modules.MinRefresh, modules.MinRefresh)}, {"type", "integer"}, {"minimum", 1}}},
			{"events", obj{{"description", "Hab event types that trigger a refresh."}, {"type", "array"}, {"uniqueItems", true}, {"items", obj{{"type", "string"}, {"pattern", modules.EventPattern}}}}},
			{"settings", obj{{"type", "array"}, {"items", setting}}},
		}},
	})
}

func kindRule(kind string, def obj) obj {
	return obj{
		{"if", obj{{"properties", obj{{"kind", obj{{"const", kind}}}}}}},
		{"then", obj{{"properties", obj{{"default", def}}}}},
	}
}

// goName turns a snake_case field or type name into an exported Go name.
func goName(s string) string {
	n := camel(s, true)
	switch n {
	case "Id":
		return "ID"
	case "Url":
		return "URL"
	}
	return n
}

// BlocksGo renders the typed Go form of every block type, for renderers such as gff's.
func BlocksGo() ([]byte, error) {
	var w bytes.Buffer
	p := func(format string, args ...any) { fmt.Fprintf(&w, format, args...) }
	p("// Code generated by internal/apigen from api/modules/vocab.go. DO NOT EDIT.\n\n")
	p("package modules\n\n")
	p("import \"encoding/json\"\n\n")
	p("// Block is one block of a tree. Exactly one of the typed fields is set for a known type; for\n")
	p("// a type this build does not know, none is, and Raw keeps the block as it came.\n")
	p("type Block struct {\n")
	p("\tType string\n")
	for _, f := range modules.Common {
		p("\t%s %s\n", goName(f.Name), goFieldType(f, false))
	}
	for _, b := range modules.Blocks {
		p("\t%s *%s\n", goName(b.Type), goName(b.Type)+"Block")
	}
	p("\tRaw json.RawMessage\n")
	p("}\n\n")

	p("type blockCommon struct {\n\tType string `json:\"type\"`\n")
	for _, f := range modules.Common {
		p("\t%s %s `json:\"%s,omitempty\"`\n", goName(f.Name), goFieldType(f, false), f.Name)
	}
	p("}\n\n")

	p("// UnmarshalJSON decodes a block by its type. Unknown fields are ignored.\n")
	p("func (b *Block) UnmarshalJSON(data []byte) error {\n")
	p("\tvar c blockCommon\n\tif err := json.Unmarshal(data, &c); err != nil {\n\t\treturn err\n\t}\n")
	p("\t*b = Block{Type: c.Type")
	for _, f := range modules.Common {
		p(", %s: c.%s", goName(f.Name), goName(f.Name))
	}
	p("}\n\tswitch c.Type {\n")
	for _, b := range modules.Blocks {
		p("\tcase %q:\n\t\tb.%s = new(%sBlock)\n\t\treturn json.Unmarshal(data, b.%s)\n", b.Type, goName(b.Type), goName(b.Type), goName(b.Type))
	}
	p("\t}\n\tb.Raw = append(json.RawMessage(nil), data...)\n\treturn nil\n}\n\n")

	p("// MarshalJSON encodes the block with its type and common fields.\n")
	p("func (b Block) MarshalJSON() ([]byte, error) {\n")
	p("\tvar body any\n\tswitch {\n")
	for _, b := range modules.Blocks {
		p("\tcase b.%s != nil:\n\t\tbody = b.%s\n", goName(b.Type), goName(b.Type))
	}
	p("\tdefault:\n\t\tif b.Raw != nil {\n\t\t\treturn b.Raw, nil\n\t\t}\n\t}\n")
	p("\tfields := map[string]json.RawMessage{}\n")
	p("\tif body != nil {\n\t\traw, err := json.Marshal(body)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n")
	p("\t\tif err := json.Unmarshal(raw, &fields); err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t}\n")
	p("\tcommon, err := json.Marshal(blockCommon{Type: b.Type")
	for _, f := range modules.Common {
		p(", %s: b.%s", goName(f.Name), goName(f.Name))
	}
	p("})\n\tif err != nil {\n\t\treturn nil, err\n\t}\n")
	p("\tif err := json.Unmarshal(common, &fields); err != nil {\n\t\treturn nil, err\n\t}\n")
	p("\treturn json.Marshal(fields)\n}\n\n")

	p("// Action is a block's action (modules.md 6.2).\n")
	p("type Action struct {\n\tName string `json:\"name\"`\n\tArgs map[string]any `json:\"args,omitempty\"`\n}\n\n")
	p("// Steps is a progress block's step count.\n")
	p("type Steps struct {\n\tTotal int `json:\"total\"`\n\tCurrent int `json:\"current\"`\n}\n\n")

	for _, b := range modules.Blocks {
		p("// %sBlock is a %s block: %s\n", goName(b.Type), b.Type, lowerFirst(b.Doc))
		p("type %sBlock struct {\n", goName(b.Type))
		for _, f := range b.Fields {
			tag := f.Name
			if !f.Required {
				tag += ",omitempty"
			}
			if f.Doc != "" {
				p("\t// %s\n", f.Doc)
			}
			p("\t%s %s `json:\"%s\"`\n", goName(f.Name), goFieldType(f, !f.Required), tag)
		}
		p("}\n\n")
	}
	return format.Source(w.Bytes())
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

// goFieldType is a field's Go type. optional makes a value whose zero is meaningful a pointer.
func goFieldType(f modules.Field, optional bool) string {
	switch f.Kind {
	case modules.KindBool:
		if optional {
			return "*bool"
		}
		return "bool"
	case modules.KindInt:
		if optional && f.Min <= 0 {
			return "*int"
		}
		return "int"
	case modules.KindFraction:
		return "*float64"
	case modules.KindAction:
		if optional {
			return "*Action"
		}
		return "Action"
	case modules.KindSteps:
		return "*Steps"
	case modules.KindChildren:
		return "[]Block"
	case modules.KindLines:
		return "[]string"
	}
	return "string"
}

// BlocksSwift renders the block types for the app's renderer: a Block with its common fields
// and a BlockContent enum with one case per type, plus .unknown for a type this build does not
// know, which the renderer draws as the fallback text.
func BlocksSwift() []byte {
	var w bytes.Buffer
	p := func(format string, args ...any) { fmt.Fprintf(&w, format, args...) }
	p("// Code generated by internal/apigen from api/modules/vocab.go. DO NOT EDIT.\n\n")
	p("import Foundation\n\n")
	p("public enum BlockVocabulary {\n")
	p("    /// The newest block vocabulary version these types draw (docs/specs/modules.md 9).\n")
	p("    public static let version = %d\n", modules.Version)
	p("    /// The block types this build knows.\n")
	var types []string
	for _, b := range modules.Blocks {
		types = append(types, b.Type)
	}
	p("    public static let types: [String] = [%s]\n", quoteList(types))
	p("    /// Colour meanings a tint may name; a tint may also be #RRGGBB.\n")
	p("    public static let tints: [String] = [%s]\n", quoteList(modules.Tints))
	p("}\n\n")

	p("/// One block of a module's tree. Unknown fields are ignored; an unknown type decodes to\n")
	p("/// `.unknown`, which a renderer draws as `fallback` or \"Needs a newer Flightdeck\".\n")
	p("public struct Block: Codable, Sendable, Hashable {\n")
	for _, f := range modules.Common {
		p("    /// %s\n", f.Doc)
		p("    public var %s: %s?\n", swiftIdent(camel(f.Name, false)), swiftFieldType("", f))
	}
	p("    public var content: BlockContent\n\n")
	p("    enum CommonKeys: String, CodingKey {\n        case type = \"type\"\n")
	for _, f := range modules.Common {
		p("        case %s = %q\n", swiftIdent(camel(f.Name, false)), f.Name)
	}
	p("    }\n\n")
	var args, sets []string
	for _, f := range modules.Common {
		id := swiftIdent(camel(f.Name, false))
		args = append(args, fmt.Sprintf("%s: %s? = nil", id, swiftFieldType("", f)))
		sets = append(sets, fmt.Sprintf("        self.%s = %s\n", id, id))
	}
	p("    public init(_ content: BlockContent, %s) {\n        self.content = content\n%s    }\n\n", strings.Join(args, ", "), strings.Join(sets, ""))
	p("    /// The block's type word.\n")
	p("    public var type: String {\n        switch content {\n")
	for _, b := range modules.Blocks {
		p("        case .%s: return %q\n", swiftIdent(camel(b.Type, false)), b.Type)
	}
	p("        case .unknown(let type): return type\n        }\n    }\n\n")
	p("    public init(from decoder: Decoder) throws {\n")
	p("        let c = try decoder.container(keyedBy: CommonKeys.self)\n")
	for _, f := range modules.Common {
		id := swiftIdent(camel(f.Name, false))
		p("        %s = try c.decodeIfPresent(%s.self, forKey: .%s)\n", id, swiftFieldType("", f), id)
	}
	p("        switch try c.decode(String.self, forKey: .type) {\n")
	for _, b := range modules.Blocks {
		p("        case %q: content = .%s(try %s(from: decoder))\n", b.Type, swiftIdent(camel(b.Type, false)), swiftBlockName(b.Type))
	}
	p("        case let other: content = .unknown(type: other)\n        }\n    }\n\n")
	p("    public func encode(to encoder: Encoder) throws {\n")
	p("        switch content {\n")
	for _, b := range modules.Blocks {
		p("        case .%s(let b): try b.encode(to: encoder)\n", swiftIdent(camel(b.Type, false)))
	}
	p("        case .unknown: break\n        }\n")
	p("        var c = encoder.container(keyedBy: CommonKeys.self)\n")
	p("        try c.encode(type, forKey: .type)\n")
	for _, f := range modules.Common {
		id := swiftIdent(camel(f.Name, false))
		p("        try c.encodeIfPresent(%s, forKey: .%s)\n", id, id)
	}
	p("    }\n}\n\n")

	p("/// What a block draws, by its type.\n")
	p("public enum BlockContent: Sendable, Hashable {\n")
	for _, b := range modules.Blocks {
		p("    /// %s\n", b.Doc)
		p("    case %s(%s)\n", swiftIdent(camel(b.Type, false)), swiftBlockName(b.Type))
	}
	p("    /// A type this build does not know.\n")
	p("    case unknown(type: String)\n}\n\n")

	p("/// A block's action (docs/specs/modules.md 6.2). A client.* name is handled by the client.\n")
	p("public struct BlockAction: Codable, Sendable, Hashable {\n")
	p("    public var name: String\n    public var args: [String: JSONValue]?\n\n")
	p("    public init(name: String, args: [String: JSONValue]? = nil) {\n        self.name = name\n        self.args = args\n    }\n}\n\n")
	p("/// A progress block's step count.\n")
	p("public struct ProgressSteps: Codable, Sendable, Hashable {\n")
	p("    public var total: Int\n    public var current: Int\n\n")
	p("    public init(total: Int, current: Int) {\n        self.total = total\n        self.current = current\n    }\n}\n\n")
	swiftWords(&w, "BlockTint", &Schema{KnownValues: modules.Tints})

	for _, b := range modules.Blocks {
		for _, f := range b.Fields {
			if f.Kind == modules.KindWords {
				swiftWords(&w, swiftWordsName(b.Type, f.Name), &Schema{KnownValues: f.Words})
			}
		}
	}

	for _, b := range modules.Blocks {
		name := swiftBlockName(b.Type)
		p("/// %s\n", b.Doc)
		p("public struct %s: Codable, Sendable, Hashable {\n", name)
		type field struct{ id, json, typ string }
		var fields []field
		for _, f := range b.Fields {
			t := swiftFieldType(b.Type, f)
			if !f.Required {
				t += "?"
			}
			fl := field{swiftIdent(camel(f.Name, false)), f.Name, t}
			fields = append(fields, fl)
			if f.Doc != "" {
				p("    /// %s\n", f.Doc)
			}
			p("    public var %s: %s\n", fl.id, fl.typ)
		}
		p("\n    enum CodingKeys: String, CodingKey {\n")
		for _, f := range fields {
			p("        case %s = %q\n", f.id, f.json)
		}
		p("    }\n\n")
		var args, sets []string
		for _, f := range fields {
			a := f.id + ": " + f.typ
			if strings.HasSuffix(f.typ, "?") {
				a += " = nil"
			}
			args = append(args, a)
			sets = append(sets, fmt.Sprintf("        self.%s = %s\n", f.id, f.id))
		}
		p("    public init(%s) {\n%s    }\n}\n\n", strings.Join(args, ", "), strings.Join(sets, ""))
	}
	return append(bytes.TrimRight(w.Bytes(), "\n"), '\n')
}

func swiftBlockName(t string) string { return camel(t, true) + "Block" }

func swiftWordsName(blockType, field string) string {
	return camel(blockType, true) + camel(field, true)
}

func swiftFieldType(blockType string, f modules.Field) string {
	switch f.Kind {
	case modules.KindBool:
		return "Bool"
	case modules.KindInt:
		return "Int"
	case modules.KindFraction:
		return "Double"
	case modules.KindWords:
		return swiftWordsName(blockType, f.Name)
	case modules.KindTint:
		return "BlockTint"
	case modules.KindAction:
		return "BlockAction"
	case modules.KindSteps:
		return "ProgressSteps"
	case modules.KindChildren:
		return "[Block]"
	case modules.KindLines:
		return "[String]"
	}
	return "String"
}
